@CrossOrigin
@RestController
@RequestMapping("/RecordsRepositoryQuery")
public class RecordsRepositoryQueryRestController extends BaseSpringRestController {
	
	public RecordsRepositoryQueryRestController( RecordsRepositoryService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a RecordsRepository using a UUID
     * @param		UUID recordsRepositoryId
     * @return		RecordsRepository
     */    
    @GetMapping("/load")
    public RecordsRepository load( @RequestParam(required=true) UUID recordsRepositoryId ) {
    	RecordsRepository entity = null;

    	try {  
    		entity = service.getRecordsRepository( new RecordsRepositoryFetchOneSummary( recordsRepositoryId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load RecordsRepository using Id " + recordsRepositoryId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all RecordsRepository business objects
     * @return		Set<RecordsRepository>
     */
    @GetMapping("/")
    public List<RecordsRepository> loadAll() {                
    	List<RecordsRepository> recordsRepositoryList = null;
        
    	try {
            // load the RecordsRepository
            recordsRepositoryList = service.getAllRecordsRepository();
            
            if ( recordsRepositoryList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all RecordsRepositorys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all RecordsRepositorys ", exc );
        	return null;
        }

        return recordsRepositoryList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected RecordsRepository recordsRepository = null;
    protected RecordsRepositoryService service = null;
    private static final Logger LOGGER = Logger.getLogger(RecordsRepositoryQueryRestController.class.getName());
    
}
